#include <stdio.h>

int main() 
{ 
    int arr1[] = {1, 2, 3, 4, 5}; 
    int arr2[] = {4, 5, 6, 7, 8}; 
    int i, j; 

    // Printing elements of first array 
    printf("Array 1: "); 
    for (i = 0; i < 5; i++) 
        printf("%d ", arr1[i]); 
    printf("\n"); 

    // Printing elements of second array 
    printf("Array 2: "); 
    for (i = 0; i < 5; i++) 
        printf("%d ", arr2[i]); 
    printf("\n"); 

    // Finding common elements 
    printf("Common elements: "); 
    for (i = 0; i < 5; i++) { 
        for (j = 0; j < 5; j++) { 
            if (arr1[i] == arr2[j]) 
                printf("%d ", arr1[i]); 
        } 
    } 

    return 0; 
} 

