    <ul class="messages"></ul>
  </div>

  <script>
    // Array of chat messages
    const messages = [
      "Hi there!",
      "How can I help you today?",
      "I'm sorry, I'm just a chatbot. I don't have any real information to give you.",
      "That's too bad. Well, have a nice day!"
    ];

    // Array of chat participants
    const participants = [
      "User",
      "Chatbot"
    ];

    // Function to display the chat window
    function showChat() {
      const chat = document.querySelector(".chat");
      chat.style.display = "block";
    }

    // Function to hide the chat window
    function hideChat() {
      const chat = document.querySelector(".chat");
      chat.style.display = "none";
    }

    // Function to add a chat message to the list
    function addMessage(who, text) {
      const messageList = document.querySelector(".messages");
      const message = document.createElement("li");
      message.classList.add(who);
      message.textContent = text;
      messageList.appendChild(message);
    }

    // Function to send a message
